import sys

MOD = 998244353

def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    if not data:
        return
    n, m = data[0], data[1]

    # For each center x and right endpoint r, retain the largest left
    # endpoint among constraints with center x and right endpoint at most r.
    # Such a constraint is contained in [l, r] exactly when this value >= l.
    max_left = [[-1] * (n + 1) for _ in range(n + 1)]
    pos = 2
    for _ in range(m):
        left, right, x = data[pos], data[pos + 1], data[pos + 2]
        pos += 3
        if left > max_left[x][right]:
            max_left[x][right] = left

    for x in range(1, n + 1):
        best = -1
        row = max_left[x]
        for r in range(1, n + 1):
            if row[r] > best:
                best = row[r]
            row[r] = best

    fact = [1] * (n + 1)
    inv_fact = [1] * (n + 1)
    for i in range(1, n + 1):
        fact[i] = fact[i - 1] * i % MOD
    inv_fact[n] = pow(fact[n], MOD - 2, MOD)
    for i in range(n, 0, -1):
        inv_fact[i - 1] = inv_fact[i] * i % MOD

    choose = [[0] * (n + 1) for _ in range(n + 1)]
    for a in range(n + 1):
        for b in range(a + 1):
            choose[a][b] = fact[a] * inv_fact[b] % MOD * inv_fact[a - b] % MOD

    dp = [[0] * (n + 2) for _ in range(n + 2)]
    for i in range(1, n + 2):
        dp[i][i - 1] = 1

    for length in range(1, n + 1):
        for left in range(1, n - length + 2):
            right = left + length - 1
            total = 0
            for root in range(left, right + 1):
                # If a constraint centered at root lies wholly in this
                # interval, choosing root as its maximum violates it.
                if max_left[root][right] >= left:
                    continue
                left_size = root - left
                total += (dp[left][root - 1] * dp[root + 1][right]
                          % MOD) * choose[length - 1][left_size]
                total %= MOD
            dp[left][right] = total

    print(dp[1][n])

if __name__ == '__main__':
    main()

