import sys
MOD = 998244353

def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    if not data:
        return
    n = data[0]
    values = data[1:]

    factors = []
    primes = set()
    for x in values:
        fs = {}
        d = 2
        while d * d <= x:
            while x % d == 0:
                fs[d] = fs.get(d, 0) + 1
                x //= d
            d += 1
        if x > 1:
            fs[x] = fs.get(x, 0) + 1
        factors.append(fs)
        primes.update(fs)

    answer = 1
    for p in primes:
        steps = [fs.get(p, 0) for fs in factors]
        bound = sum(steps)
        p_powers = [pow(p, h, MOD) for h in range(bound + 1)]

        # dp[height][0/1]: weighted paths, where the flag records
        # whether height zero has appeared among the vertices so far.
        dp = [[0, 0] for _ in range(bound + 1)]
        for h in range(bound + 1):
            dp[h][1 if h == 0 else 0] = p_powers[h]

        for step in steps:
            ndp = [[0, 0] for _ in range(bound + 1)]
            for h, states in enumerate(dp):
                for touched in (0, 1):
                    ways = states[touched]
                    if not ways:
                        continue
                    if step == 0:
                        destinations = (h,)
                    else:
                        destinations = (h - step, h + step)
                    for nh in destinations:
                        if nh < 0 or nh > bound:
                            continue
                        flag = 1 if touched or nh == 0 else 0
                        ndp[nh][flag] = (ndp[nh][flag] + ways * p_powers[nh]) % MOD
            dp = ndp

        contribution = sum(states[1] for states in dp) % MOD
        answer = answer * contribution % MOD

    print(answer)

if __name__ == '__main__':
    main()

