from typing import List
import heapq
class Solution:
    def maxSubarrays(self, n: int, conflictingPairs: List[List[int]]) -> int:
        events=[[] for _ in range(n+1)]
        for i,(a,b) in enumerate(conflictingPairs):
            if a>b: a,b=b,a
            events[b].append((a,i))
        heap=[]
        base=0
        gain=[0]*len(conflictingPairs)
        for r in range(1,n+1):
            for a,i in events[r]: heapq.heappush(heap,(-a,i))
            if not heap:
                base+=r
                continue
            first=heapq.heappop(heap)
            top=-first[0]
            if heap:
                second=-heap[0][0]
            else:
                second=0
            heapq.heappush(heap,first)
            base+=r-top
            if second<top: gain[first[1]]+=top-second
        return base+max(gain)

