import sys

def main():
    input = sys.stdin.buffer.readline
    N, M, Q = map(int, input().split())
    edges = []
    for _ in range(M):
        a, b, c = map(int, input().split())
        edges.append((a - 1, b - 1, c))

    queries = []
    closed = [False] * M
    for _ in range(Q):
        z = list(map(int, input().split()))
        if z[0] == 1:
            i = z[1] - 1
            closed[i] = True
            queries.append((1, i))
        else:
            queries.append((2, z[1] - 1, z[2] - 1))

    INF = 10**30
    dist = [[INF] * N for _ in range(N)]
    for i in range(N):
        dist[i][i] = 0
    for i, (a, b, c) in enumerate(edges):
        if not closed[i]:
            dist[a][b] = dist[b][a] = c

    # APSP in the graph after all forward deletions.
    for k in range(N):
        row_k = dist[k]
        for i in range(N):
            dik = dist[i][k]
            if dik == INF:
                continue
            row_i = dist[i]
            for j in range(N):
                nd = dik + row_k[j]
                if nd < row_i[j]:
                    row_i[j] = nd

    answers = []
    # Reverse time: each deletion becomes an edge insertion.
    for query in reversed(queries):
        if query[0] == 2:
            value = dist[query[1]][query[2]]
            answers.append(-1 if value == INF else value)
        else:
            u, v, w = edges[query[1]]
            row_u = dist[u][:]
            row_v = dist[v][:]
            for i in range(N):
                iu = dist[i][u]
                iv = dist[i][v]
                row_i = dist[i]
                if iu != INF:
                    for j in range(N):
                        nd = iu + w + row_v[j]
                        if nd < row_i[j]:
                            row_i[j] = nd
                if iv != INF:
                    for j in range(N):
                        nd = iv + w + row_u[j]
                        if nd < row_i[j]:
                            row_i[j] = nd

    sys.stdout.write('\n'.join(map(str, reversed(answers))))

if __name__ == '__main__':
    main()

