import sys
from itertools import permutations

def main():
    A, B, M = map(int, sys.stdin.buffer.read().split())
    n = A * B - 1
    # Exhaustively enumerate permutations. For each one, compute the LIS/LDS
    # tail arrays and check whether a half-integer can be appended without
    # increasing either length.
    ans = 0
    for p in permutations(range(1, n + 1)):
        inc = []
        dec = []
        for v in p:
            lo, hi = 0, len(inc)
            while lo < hi:
                mid = (lo + hi) // 2
                if inc[mid] < v:
                    lo = mid + 1
                else:
                    hi = mid
            if lo == len(inc):
                inc.append(v)
            else:
                inc[lo] = v
            lo, hi = 0, len(dec)
            while lo < hi:
                mid = (lo + hi) // 2
                if dec[mid] > v:
                    lo = mid + 1
                else:
                    hi = mid
            if lo == len(dec):
                dec.append(v)
            else:
                dec[lo] = v
        if len(inc) != A or len(dec) != B:
            continue
        # inc[-1] is the minimum possible endpoint of a longest increasing
        # subsequence; dec[-1] is the maximum endpoint of a longest decreasing
        # subsequence. A half-integer in between preserves both lengths.
        if dec[-1] < inc[-1]:
            ans += 1
    print(ans % M)

if __name__ == '__main__':
    main()

