import sys
import math

def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    if not data:
        return
    n, budget = data[:2]
    processes = [tuple(data[i:i + 4]) for i in range(2, len(data), 4)]

    def affordable(target):
        total = 0
        for a, p, b, q in processes:
            if target == 0:
                continue

            # Counts x of S machines that leave a positive remainder to T.
            xmax = (target - 1) // a
            period = b // math.gcd(a, b)
            best = ((target + a - 1) // a) * p  # T count is zero

            # Within each residue modulo period, costs vary linearly as x grows,
            # so the minimum occurs at one of the two ends of the feasible range.
            for r in range(min(period, xmax + 1)):
                last = r + ((xmax - r) // period) * period
                for x in (r, last):
                    y = (target - a * x + b - 1) // b
                    best = min(best, p * x + q * y)

            total += best
            if total > budget:
                return False
        return total <= budget

    lo, hi = 0, budget * 100 + 1
    while lo + 1 < hi:
        mid = (lo + hi) // 2
        if affordable(mid):
            lo = mid
        else:
            hi = mid
    print(lo)

if __name__ == '__main__':
    main()

