from math import comb

class Solution:
    def countKReducibleNumbers(self, s: str, k: int) -> int:
        mod = 10**9 + 7
        n = len(s)
        ways = [0] * (n + 1)
        used = 0

        # Count values smaller than s, grouped by their number of set bits.
        for i, bit in enumerate(s):
            if bit == '1':
                remaining = n - i - 1
                for total in range(used, n + 1):
                    choose = total - used
                    if choose <= remaining:
                        ways[total] += comb(remaining, choose)
                used += 1

        answer = 0
        for ones in range(1, n + 1):
            value = ones
            operations = 0
            while value != 1:
                value = value.bit_count()
                operations += 1
            # A number with this many set bits first takes one operation
            # to become 'ones'.
            if operations + 1 <= k:
                answer += ways[ones]

        return answer % mod

