from collections import deque

def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    if not data:
        return
    it = iter(data)
    N, M, Q = next(it), next(it), next(it)
    people = [(next(it)-1, next(it)-1) for _ in range(M)]
    queries = [(next(it)-1, next(it)-1) for _ in range(Q)]
    ans = []
    for L, R in queries:
        par = list(range(N))
        size = [1] * N
        def find(x):
            while par[x] != x:
                par[x] = par[par[x]]
                x = par[x]
            return x
        for i in range(L, R+1):
            a, b = people[i]
            x, y = find(a), find(b)
            if x != y:
                if size[x] < size[y]: x, y = y, x
                par[y] = x
                size[x] += size[y]
        adj = [[] for _ in range(N)]
        indeg = [0] * N
        for i in range(L, R+1):
            s, t = people[i]
            a, b = min(s,t), max(s,t)
            root = find(s)
            if s < t:
                for x in range(s+1, t):
                    v = find(x)
                    if v != root:
                        adj[root].append(v)
                        indeg[v] += 1
            else:
                for x in range(t+1, s):
                    v = find(x)
                    if v != root:
                        adj[v].append(root)
                        indeg[root] += 1
        roots = [i for i in range(N) if find(i) == i]
        q = deque(i for i in roots if indeg[i] == 0)
        seen = 0
        while q:
            u = q.popleft(); seen += 1
            for v in adj[u]:
                indeg[v] -= 1
                if indeg[v] == 0: q.append(v)
        ans.append('Yes' if seen == len(roots) else 'No')
    print('\n'.join(ans))

