import sys

# Mountain/valley fold sequence: a crease j is mountain iff the bit immediately
# above its least significant set bit is zero.
def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    n = data[0]
    A = data[1:]
    # Maintain all low-bit prefixes that still have an unresolved offset.
    # A prefix is (residue, depth, already resolved mountain count).
    active = [(0, 0, 0)]
    ans = 0
    limit_bits = 100
    for b in range(limit_bits):
        mod = 1 << (b + 1)
        nxt = {}
        for r, depth, score in active:
            for bit in (0, 1):
                nr = r + (bit << b)
                ns = score
                unresolved = False
                for a in A:
                    y = (nr + a) % mod
                    low = y & -y
                    # If y is zero modulo 2^(b+1), or its only set bit is
                    # at position b, more bits are needed to decide its type.
                    if y == 0 or y == (1 << b):
                        unresolved = True
                    else:
                        t = low.bit_length() - 1
                        if ((y >> (t + 1)) & 1) == 0:
                            ns += 1
                if unresolved:
                    key = nr
                    # Prefix residue uniquely determines the score for resolved terms.
                    if key not in nxt or nxt[key] < ns:
                        nxt[key] = ns
                else:
                    ans = max(ans, ns)
        active = [(r, b + 1, s) for r, s in nxt.items()]
        if not active:
            break
    print(ans)

