def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    if not data:
        return
    n, m = data[0], data[1]
    rows = [0] * n
    pos = 2
    for _ in range(m):
        u, v = data[pos] - 1, data[pos + 1] - 1
        pos += 2
        rows[u] |= 1 << v
        rows[v] |= 1 << u

    # Reduce the adjacency matrix over GF(2) to reduced row echelon form.
    rank = 0
    pivots = []
    for col in range(n):
        pivot = next((i for i in range(rank, n) if (rows[i] >> col) & 1), None)
        if pivot is None:
            continue
        rows[rank], rows[pivot] = rows[pivot], rows[rank]
        for i in range(n):
            if i != rank and ((rows[i] >> col) & 1):
                rows[i] ^= rows[rank]
        pivots.append((col, rank))
        rank += 1

    pivot_cols = {col for col, _ in pivots}
    free_cols = [col for col in range(n) if col not in pivot_cols]

    # Each nullspace basis vector becomes one bit in the vertex labels.
    labels = [0] * n
    for bit, free_col in enumerate(free_cols):
        vector = 1 << free_col
        for pivot_col, row_idx in pivots:
            if (rows[row_idx] >> free_col) & 1:
                vector |= 1 << pivot_col
        for v in range(n):
            if (vector >> v) & 1:
                labels[v] |= 1 << bit

    if any(value == 0 for value in labels):
        print("No")
    else:
        print("Yes")
        print(*labels)

