class Solution:
    def lenOfVDiagonal(self, grid: List[List[int]]) -> int:
        n, m = len(grid), len(grid[0])
        # Clockwise order in matrix coordinates: SE, SW, NW, NE.
        dirs = [(1, 1), (1, -1), (-1, -1), (-1, 1)]
        size = n * m

        # runs[d][v][i] is the length of a straight sequence starting at i
        # in direction d, where v=0 expects 2 and v=1 expects 0.
        runs = [[array('H', [0]) * size for _ in range(2)] for _ in range(4)]
        for d, (dr, dc) in enumerate(dirs):
            rows = range(n - 1, -1, -1) if dr == 1 else range(n)
            cols = range(m - 1, -1, -1) if dc == 1 else range(m)
            for r in rows:
                for c in cols:
                    i = r * m + c
                    nr, nc = r + dr, c + dc
                    for vi, value in enumerate((2, 0)):
                        if grid[r][c] == value:
                            tail = runs[d][1 - vi][nr * m + nc] if 0 <= nr < n and 0 <= nc < m else 0
                            runs[d][vi][i] = tail + 1

        answer = 0
        for r in range(n):
            for c in range(m):
                if grid[r][c] != 1:
                    continue
                for d, (dr, dc) in enumerate(dirs):
                    rr, cc = r, c
                    length = 1
                    answer = max(answer, length)
                    while True:
                        rr += dr
                        cc += dc
                        if not (0 <= rr < n and 0 <= cc < m):
                            break
                        expected = 2 if length % 2 == 1 else 0
                        if grid[rr][cc] != expected:
                            break
                        length += 1
                        answer = max(answer, length)

                        # Turn clockwise at (rr, cc); the next value is determined
                        # by the length of the prefix including the turn cell.
                        td = (d + 1) % 4
                        tdr, tdc = dirs[td]
                        tr, tc = rr + tdr, cc + tdc
                        if 0 <= tr < n and 0 <= tc < m:
                            vi = 0 if length % 2 == 1 else 1
                            answer = max(answer, length + runs[td][vi][tr * m + tc])

        return answer

