class Solution:
    def largestPalindrome(self, n: int, k: int) -> str:
        h = (n + 1) // 2
        powers = [pow(10, i, k) for i in range(n)]
        coeff = []
        for i in range(h):
            j = n - 1 - i
            if i == j:
                coeff.append(powers[i])
            else:
                coeff.append((powers[i] + powers[j]) % k)

        # dp[i][r]: the variables from i onward can contribute residue r.
        dp = [[False] * k for _ in range(h + 1)]
        dp[h][0] = True
        for i in range(h - 1, -1, -1):
            c = coeff[i]
            nxt = dp[i + 1]
            cur = dp[i]
            for r in range(k):
                for digit in range(10):
                    if nxt[(r - digit * c) % k]:
