        rem = 0
        for i, c in enumerate(coeff):
            for digit in range(9, -1, -1):
                if i == 0 and digit == 0:
                    continue
                needed = (-rem - digit * c) % k
                if dp[i + 1][needed]:
                    half.append(str(digit))
                    rem = (rem + digit * c) % k
                    break

        half = ''.join(half)
        if n % 2:
            return half + half[:-1][::-1]
        return half + half[::-1]

