 def countNonDecreasingSubarrays(self, nums: List[int], k: int) -> int:
  n=len(nums); nxt=[n]*n; st=[]
  for i in range(n-1,-1,-1):
   while st and nums[st[-1]]<=nums[i]: st.pop()
   if st:nxt[i]=st[-1]
   st.append(i)
  pref=[0]*(n+1)
  for i,x in enumerate(nums):pref[i+1]=pref[i]+x
  LOG=n.bit_length();up=[nxt];agg=[[nums[i]*(nxt[i]-i)-(pref[nxt[i]]-pref[i]) for i in range(n)]]
  for b in range(1,LOG):
   prev=up[-1];pa=agg[-1];cur=[n]*n;ca=[0]*n
   for i in range(n):
    mid=prev[i]
    if mid<n:cur[i]=prev[mid];ca[i]=pa[i]+pa[mid]
    else:ca[i]=pa[i]
   up.append(cur);agg.append(ca)
  def cost(i,r):
   total=0;x=i
   for b in range(LOG-1,-1,-1):
    y=up[b][x]
    if y<=r:total+=agg[b][x];x=y
   return total+nums[x]*(r-x+1)-(pref[r+1]-pref[x])
  ans=0
  for i in range(n):
   lo=i-1;hi=n-1
   while lo<hi:
    mid=(lo+hi+1)//2
    if cost(i,mid)<=k:lo=mid
    else:hi=mid-1
   ans+=lo-i+1
  return ans

