import sys
from functools import cmp_to_key

def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    if not data:
        return
    n, k = data[0], data[1]
    functions = [tuple(data[i:i + 2]) for i in range(2, len(data), 2)]

    # Apply from inner to outer. The optimal outer-to-inner order is
    # descending by (A - 1) / B, so process in ascending order here.
    def compare(f, g):
        a, b = f
        c, d = g
        x = (a - 1) * d - (c - 1) * b
        return (x > 0) - (x < 0)

    functions.sort(key=cmp_to_key(compare))

    dp = [None] * (k + 1)
    dp[0] = 1
    for a, b in functions:
        for count in range(k, 0, -1):
            previous = dp[count - 1]
            if previous is not None:
                value = a * previous + b
                if dp[count] is None or value > dp[count]:
                    dp[count] = value

    print(dp[k])

if __name__ == '__main__':
    main()

