from bisect import bisect_left

class Solution:
    def shortestMatchingSubstring(self, s: str, p: str) -> int:
        parts = p.split('*')
        n = len(s)

        def occurrences(pattern: str):
            m = len(pattern)
            if m == 0:
                return []

            # Prefix-function for KMP.
            lps = [0] * m
            j = 0
            for i in range(1, m):
                while j and pattern[i] != pattern[j]:
                    j = lps[j - 1]
                if pattern[i] == pattern[j]:
                    j += 1
                    lps[i] = j

            result = []
            j = 0
            for i, ch in enumerate(s):
                while j and ch != pattern[j]:
                    j = lps[j - 1]
                if ch == pattern[j]:
                    j += 1
                    if j == m:
                        result.append(i - m + 1)
                        j = lps[j - 1]
            return result

        chunks = []
        for part in parts:
            if part:
                starts = occurrences(part)
                if not starts:
                    return -1
                chunks.append((part, starts))

        if not chunks:
            return 0

        best = n + 1
        for start in chunks[0][1]:
            end = start + len(chunks[0][0])
            # Greedily take the earliest occurrence of each later chunk
            # that does not overlap the previous chunk.
            for part, starts in chunks[1:]:
                k = bisect_left(starts, end)
                if k == len(starts):
                    break
                end = starts[k] + len(part)
            else:
                best = min(best, end - start)

        return -1 if best == n + 1 else best

