from typing import List

class Solution:
    def findAnswer(self, parent: List[int], s: str) -> List[bool]:
        n = len(parent)
        children = [[] for _ in range(n)]
        for i in range(1, n):
            children[parent[i]].append(i)

        # Iterative postorder traversal, preserving increasing child order.
        order = []
        stack = [(0, False)]
        while stack:
            x, done = stack.pop()
            if done:
                order.append(x)
            else:
                stack.append((x, True))
                for y in reversed(children[x]):
                    stack.append((y, False))

        # The postorder string of each subtree is a contiguous interval;
        # its root is the final character in that interval.
        pos = [0] * n
        postorder = []
        for i, x in enumerate(order):
            pos[x] = i
            postorder.append(s[x])

        size = [1] * n
        for x in order:
            if parent[x] != -1:
                size[parent[x]] += size[x]

        # Manacher radii for constant-time palindrome interval checks.
        odd = [0] * n
        left, right = 0, -1
        for i in range(n):
            k = 1 if i > right else min(odd[left + right - i], right - i + 1)
            while i - k >= 0 and i + k < n and postorder[i - k] == postorder[i + k]:
                k += 1
            odd[i] = k
            if i + k - 1 > right:
                left, right = i - k + 1, i + k - 1

        even = [0] * n
        left, right = 0, -1
        for i in range(n):
            k = 0 if i > right else min(even[left + right - i + 1], right - i + 1)
            while i - k - 1 >= 0 and i + k < n and postorder[i - k - 1] == postorder[i + k]:
                k += 1
            even[i] = k
            if i + k - 1 > right:
                left, right = i - k, i + k - 1

        answer = [False] * n
        for x in range(n):
            length = size[x]
            start = pos[x] - length + 1
            if length % 2:
                answer[x] = odd[start + length // 2] >= length // 2 + 1
            else:
                answer[x] = even[start + length // 2] >= length // 2
        return answer

