from typing import List

class Solution:
    def maxSubarraySum(self, nums: List[int], k: int) -> int:
        # Minimum prefix sum seen at each index residue modulo k.
        min_prefix = [None] * k
        min_prefix[0] = 0  # Prefix before the array, at index 0.

        prefix = 0
        answer = None
        for i, value in enumerate(nums, 1):
            prefix += value
            residue = i % k

            # Pair with an earlier prefix of the same residue, so the
            # subarray length is positive and divisible by k.
            if min_prefix[residue] is not None:
                candidate = prefix - min_prefix[residue]
                if answer is None or candidate > answer:
                    answer = candidate

            if min_prefix[residue] is None or prefix < min_prefix[residue]:
                min_prefix[residue] = prefix

        return answer

