from typing import List

class Solution:
    def beautifulSplits(self, nums: List[int]) -> int:
        n = len(nums)
        if n < 3:
            return 0

        # z[i] is the LCP of nums and nums[i:].
        z = [0] * n
        z[0] = n
        left = right = 0
        for i in range(1, n):
            if i < right:
                z[i] = min(right - i, z[i - left])
            while i + z[i] < n and nums[z[i]] == nums[i + z[i]]:
                z[i] += 1
            if i + z[i] > right:
                left, right = i, i + z[i]

        answer = 0
        for start in range(1, n - 1):
            length = n - start
            # Compute Z values on the suffix nums[start:]. For a split with
            # second part of length d, nums2 is a prefix of nums3 iff z[d] >= d.
            zz = [0] * length
            left = right = 0
            for d in range(1, length):
                if d < right:
                    zz[d] = min(right - d, zz[d - left])
                while (d + zz[d] < length and
                       nums[start + zz[d]] == nums[start + d + zz[d]]):
                    zz[d] += 1
                if d + zz[d] > right:
                    left, right = d, d + zz[d]

                # The first condition is possible only when nums2 is at
                # least as long as nums1, i.e. d >= start.
                first_condition = d >= start and z[start] >= start
                if first_condition or zz[d] >= d:
                    answer += 1
        return answer

