from typing import List

class Solution:
    def maxRemovals(self, source: str, pattern: str, targetIndices: List[int]) -> int:
        m = len(pattern)
        neg = -10**9
        dp = [neg] * (m + 1)
        dp[0] = 0
        targets = set(targetIndices)

        for i, ch in enumerate(source):
            # Retain this character without using it in the subsequence.
            ndp = dp.copy()

            # Or remove it, if its index is eligible.
            if i in targets:
                for j in range(m + 1):
                    if dp[j] != neg:
                        ndp[j] = max(ndp[j], dp[j] + 1)

            # Or retain it as the next character of pattern.
            for j in range(m):
                if ch == pattern[j] and dp[j] != neg:
                    ndp[j + 1] = max(ndp[j + 1], dp[j])

            dp = ndp

        return dp[m]

