class Solution:
    def minMaxWeight(self, n: int, edges: List[List[int]], threshold: int) -> int:
        # Traverse backward from 0: an incoming edge u -> v means u can
        # reach 0 if v can reach 0.
        reverse = [[] for _ in range(n)]
        for u, v, w in edges:
            reverse[v].append((u, w))

        weights = sorted({w for _, _, w in edges})

        def feasible(limit: int) -> bool:
            seen = [False] * n
            seen[0] = True
            stack = [0]
            count = 1
            while stack:
                v = stack.pop()
                for u, w in reverse[v]:
                    if w <= limit and not seen[u]:
                        seen[u] = True
                        count += 1
                        stack.append(u)
            return count == n

        left, right = 0, len(weights) - 1
        answer = -1
        while left <= right:
            mid = (left + right) // 2
            if feasible(weights[mid]):
                answer = weights[mid]
                right = mid - 1
            else:
                left = mid + 1
        return answer

