class Solution:
    def minCost(self, n: int, cost: List[List[int]]) -> int:
        # A state paints one mirrored pair (left, right). The two colors
        # within every pair must differ.
        states = [(a, b) for a in range(3) for b in range(3) if a != b]
        dp = [cost[0][a] + cost[n - 1][b] for a, b in states]

        for i in range(1, n // 2):
            next_dp = [float('inf')] * len(states)
            for prev_idx, (a, b) in enumerate(states):
                base = dp[prev_idx]
                for cur_idx, (c, d) in enumerate(states):
                    # The corresponding houses on both sides are adjacent.
                    if c != a and d != b:
                        value = base + cost[i][c] + cost[n - 1 - i][d]
                        if value < next_dp[cur_idx]:
                            next_dp[cur_idx] = value
            dp = next_dp

        return min(dp)

