class Solution:
    def maxActiveSectionsAfterTrade(self, s: str) -> int:
        t = '1' + s + '1'
        runs = []
        current = t[0]
        length = 0

        for ch in t:
            if ch == current:
                length += 1
            else:
                runs.append((current, length))
                current = ch
                length = 1
        runs.append((current, length))

        best_gain = 0
        for i in range(1, len(runs) - 1):
            if runs[i][0] == '1':
                # Remove this 1-run; the adjacent zero-runs merge with it,
                # and the merged zero-run can then be turned into ones.
                best_gain = max(best_gain, runs[i - 1][1] + runs[i + 1][1])

        return s.count('1') + best_gain

